import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const images = Array.from({ length: 40 }, (_, i) =>
  `/images/a${(i % 3) + 1}.gif` // just repeating a1, a2, a3
);

function Home() {
  const [selectedImages, setSelectedImages] = useState([]);
  const navigate = useNavigate();

  const toggleImage = (img) => {
    setSelectedImages((prev) =>
      prev.includes(img) ? prev.filter((i) => i !== img) : [...prev, img]
    );
  };

  const handleGenerate = () => {
    // Save selected to localStorage for now
    localStorage.setItem("selectedImages", JSON.stringify(selectedImages));
    navigate("/generate");
  };

  return (
    <div>
      <h1>Select Images</h1>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "10px",
          padding: "20px",
        }}
      >
        {images.map((img, i) => (
          <img
            key={i}
            src={img}
            alt={`tile-${i}`}
            onClick={() => toggleImage(img)}
            style={{
              width: "100%",
              cursor: "pointer",
              border: selectedImages.includes(img) ? "3px solid yellow" : "1px solid gray",
              borderRadius: "8px",
            }}
          />
        ))}
      </div>
      <button
        onClick={handleGenerate}
        disabled={selectedImages.length < 2}
        style={{ margin: "20px", padding: "10px 20px", fontSize: "16px" }}
      >
        Generate
      </button>
    </div>
  );
}

export default Home;
